const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function localizedGift(name,label=''){return window.GiftStreamI18n?.getLang()==='en'?(name||label||'Gift'):(giftPL[name]||label||name||'Prezent')}
