function bindGiftArt(root=document){root.querySelectorAll('img[data-tiktok-art]').forEach(img=>img.onerror=()=>{if(!state.artRecoveryAttempted){state.artRecoveryAttempted=true;post('/api/gifts/refresh').then(()=>fillGifts()).catch(()=>{})}const fallback=document.createElement('span');fallback.className=`${img.className} gift-art-placeholder`;fallback.setAttribute('aria-hidden','true');fallback.title='Artwork is temporarily unavailable — try refreshing the catalog';fallback.innerHTML=giftBoxSvg;const card=img.closest('.gift-library-card'),source=card?.querySelector('.gift-source');if(source){source.textContent='ARTWORK UNAVAILABLE';source.classList.remove('real')}img.replaceWith(fallback)})}
