async function api(path,opt={}){const r=await fetch(path,{cache:'no-store',headers:{'Content-Type':'application/json'},...opt});const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.detail||'The request could not be completed');return data}
