function closeMobileNav(){const wasOpen=document.body.classList.contains('sidebar-open');document.body.classList.remove('sidebar-open');const menu=$('#menu-toggle');menu?.setAttribute('aria-expanded','false');menu?.setAttribute('aria-label','Open menu');if(wasOpen&&window.innerWidth<=800)menu?.focus()}
function setView(name,pushHistory=true){if(!$(`#view-${name}`))name='overview';$$('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${name}`));$$('.nav-link').forEach(a=>{const active=a.dataset.view===name;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#crumb-current').textContent=({overview:'Dashboard',presets:'Game rules',events:'Activity',gifts:'Gift library',sounds:'Sounds & alerts',overlay:'OBS overlay',bridge:'Minecraft setup'})[name]||name;if(pushHistory&&location.hash!==`#${name}`)history.pushState({view:name},'',`#${name}`);closeMobileNav();if(name!=='events'&&$('#event-search')?.value){$('#event-search').value='';renderFeed()}if(name==='overlay')updateOverlayPreview();if(name==='gifts')loadGiftLibrary();window.scrollTo({top:0,behavior:'smooth'})}
const plnText=value=>`${Number(value||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})} PLN`;
function giftPayout(diamonds,count=1){return Math.max(0,Number(diamonds)||0)*Math.max(1,Number(count)||1)*state.earningsSettings.usd_per_diamond*state.earningsSettings.usd_to_pln}
function eventDescriptionCore(e){if(e.type==='gift'){const gift=findGift(e.gift_name,e.gift_id),diamonds=Number(e.earning_diamonds??e.diamonds)||0,repeat=Math.max(1,Number(e.repeat_count)||1),eventCoins=!e.gift_coins_estimated?Number(e.gift_coins)||0:0,catalogCoins=gift&&!gift.coins_estimated?Number(gift.coins)||0:0,coinValue=eventCoins||catalogCoins,price=coinValue?`${coinText(coinValue*repeat)} in total from the viewer`:'price not reported by TikTok',payout=e.repeat_end===false?'streak in progress':diamonds?`≈ ${plnText(giftPayout(diamonds,repeat))}`:'creator diamonds after LIVE sync';return `${localizedGift(e.gift_name,gift?.label_pl)}${repeat>1?` ×${repeat}`:''} · ${price} · ${payout}`};if(e.type==='comment')return `“${e.comment||''}”`;if(e.type==='like')return `Likes ×${e.like_count||1}`;return ({follow:'New follower',join:'Joined the stream',share:'Shared the stream',subscribe:'New subscription'})[e.type]||typePL[e.type]||e.type}
function eventDescription(e){const text=eventDescriptionCore(e),source=e.source==='browser'?'Browser lokalny':e.source==='tiktok'?'TikTokLive':e.source;return source?`${text} · ${source}`:text}
function timeLabel(ts){const d=new Date((ts||Date.now()/1000)*1000);return d.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit'})}
function renderFeed(){let combined=[...state.events.map(e=>({kind:'event',data:e})),...state.actions.map(a=>({kind:'action',data:a}))].sort((a,b)=>(b.data.ts||0)-(a.data.ts||0)).slice(0,200);const query=$('#event-search')?.value.trim().toLocaleLowerCase('en-US')||'';if(query)combined=combined.filter(x=>{const d=x.data,ev=x.kind==='action'?d.triggered_by:d;return `${eventDescription(ev||{})} ${ev?.nickname||''} ${ev?.user||''} ${d.rule_name||''} ${d.action||''}`.toLocaleLowerCase('en-US').includes(query)});const markup=combined.map(x=>{const d=x.data;const ev=x.kind==='action'?d.triggered_by:d;const isAction=x.kind==='action';let desc=isAction?`${actionStatusPL[d.execution_status]||'AKCJA'}: ${d.rule_name||actionPL[d.action]||d.action}${d.execution_message?` · ${d.execution_message}`:''}`:eventDescription(d);return `<div class="feed-row"><div class="feed-event">${isAction?'<span class="feed-icon"><img src="/static/giftstream.svg" alt=""></span>':eventIconMarkup(ev)}<span>${isAction?`<span class="action-badge action-${esc(d.execution_status||'pending')}">${actionStatusPL[d.execution_status]||'AKCJA'}</span>`:esc(typePL[ev?.type]||'Zdarzenie')}</span></div><span class="feed-user">${esc(ev?.nickname||ev?.user||'—')}</span><span class="feed-detail">${esc(desc)}</span><span class="feed-time">${timeLabel(d.ts)}</span></div>`}).join('');$('#activity-list').innerHTML=combined.length?combined.slice(0,5).map(x=>{let d=x.data,ev=x.kind==='action'?d.triggered_by:d;return `<div class="feed-row"><div class="feed-event">${x.kind==='action'?'<span class="feed-icon"><img src="/static/giftstream.svg" alt=""></span>':eventIconMarkup(ev)}<span>${esc(typePL[ev?.type]||'Zdarzenie')}</span></div><span class="feed-user">${esc(ev?.nickname||ev?.user||'—')}</span><span class="feed-detail">${esc(x.kind==='action'?`${actionStatusPL[d.execution_status]||'AKCJA'} · ${d.execution_message||d.rule_name||actionPL[d.action]||d.action}`:eventDescription(d))}</span><span class="feed-time">${timeLabel(d.ts)}</span></div>`}).join(''):`<div class="empty-state"><span class="empty-symbol">↯</span><strong>${query?'No matching events':'Waiting for the first event'}</strong><small>${query?'Try a different search.':'Connect TikTok LIVE to see events.'}</small></div>`;$('#all-activity').innerHTML=markup||`<div class="empty-state"><span class="empty-symbol">↯</span><strong>${query?'No matching events':'No events yet'}</strong><small>${query?'Try a different search.':'Connect TikTok LIVE to see events.'}</small></div>`;bindGiftArt($('#activity-list'));bindGiftArt($('#all-activity'))}
function renderDonors(donors=[]){const max=Math.max(1,...donors.map(d=>Number(d.diamonds)||0));const rows=donors.map((d,i)=>`<div class="donor-row"><span class="donor-rank">${String(i+1).padStart(2,'0')}</span><span class="donor-avatar">${esc((d.user||'?').slice(0,1).toUpperCase())}</span><span class="donor-info"><span class="donor-name">@${esc(d.user)}</span><i style="width:${Math.max(5,Math.round((Number(d.diamonds)||0)*100/max))}%"></i></span><span class="donor-count" title="Estimate based on diamonds and configured rates">${Number(d.diamonds).toLocaleString('en-US')} diamonds · ≈ ${plnText(giftPayout(d.diamonds))}</span></div>`).join('');$('#donor-list').innerHTML=rows||'<div class="empty-note">No gifts yet. Time for chaos!</div>'}
function renderEarnings(){const total=giftPayout(state.totalDiamonds);$('#earnings-total').textContent=plnText(total);$('#earnings-diamonds').textContent=`${Number(state.totalDiamonds).toLocaleString('en-US')} diamonds`;$('#earnings-gifts').textContent=`${Number(state.totalGifts).toLocaleString('en-US')} gifts`}
function renderEarningsSettings(){const s=state.earningsSettings;$('#rate-diamond').value=s.usd_per_diamond;$('#rate-usd-pln').textContent=Number(s.usd_to_pln).toLocaleString('en-US',{minimumFractionDigits:4,maximumFractionDigits:4});$('#earnings-rate-status').textContent=s.usd_to_pln_updated?`${s.rate_source} · ${s.usd_to_pln_updated}`:s.rate_source;renderEarnings();renderFeed();renderDonors(state.donors)}
async function loadEarningsSettings(){try{state.earningsSettings=await api('/api/earnings/settings');renderEarningsSettings()}catch{}}
async function saveEarningsSettings(event){event.preventDefault();const status=$('#earnings-rate-status');try{state.earningsSettings=await api('/api/earnings/settings',{method:'PUT',body:JSON.stringify({usd_per_diamond:Number($('#rate-diamond').value)})});renderEarningsSettings();if(state.displayGifts.length)renderGiftLibrary();toast('Diamond value assumption saved')}catch(e){status.textContent=e.message;toast(e.message)}}
async function refreshNbpRate(){const button=$('#refresh-nbp');button.disabled=true;try{const result=await post('/api/earnings/refresh-rate');state.earningsSettings=result.settings;renderEarningsSettings();toast(result.ok?'NBP rate updated':result.message)}catch(e){toast(e.message)}finally{button.disabled=false}}
function renderActive(){const p=state.active;if(!p)return;$('#active-preset-name').textContent=p.name;const rules=p.rules||[];$('#active-rule-total').textContent=rules.filter(r=>r.enabled).length;$('#nav-rule-count').textContent=rules.filter(r=>r.enabled).length;$('#rule-preview').innerHTML=rules.filter(r=>r.enabled).slice(0,4).map(r=>`<div class="rule-preview-row"><span>${esc((r.trigger.type==='gift'?localizedGift(r.trigger.gift_name):r.trigger.keyword||typePL[r.trigger.type]||r.trigger.type))}</span><span class="mini-arrow">→</span><b>${esc(actionPL[r.action.type]||r.action.type.replaceAll('_',' '))}</b></div>`).join('')||'<div class="empty-note">This preset has no rules yet.</div>';}
function syncModeToPreset(id){$('#parkour-game-mode').value=id==='minecraft-dropper'?'dropper':'parkour';updateMinecraftModeUI()}
function renderPresets(){const list=$('#preset-list');list.innerHTML=state.presets.map(p=>`<button class="preset-item ${state.selected?.id===p.id?'selected':''}" data-preset="${esc(p.id)}"><span class="preset-glyph">⌘</span><span class="preset-item-info"><b>${esc(p.name)}</b><small>${p.rules.filter(r=>r.enabled).length} active rules</small></span>${p.id===state.active?.id?'<span class="active-tag">LIVE</span>':''}</button>`).join('');$$('.preset-item').forEach(b=>b.onclick=()=>selectPreset(b.dataset.preset));renderRules()}
function moveRule(ruleId,delta){
  const p=state.selected;if(!p)return;
  const from=p.rules.findIndex(r=>r.id===ruleId),to=from+delta;
  if(from<0||to<0||to>=p.rules.length)return;
  const [rule]=p.rules.splice(from,1);
  p.rules.splice(to,0,rule);
  renderRules();saveSelected();toast('Rule order saved');
}
let dragRuleId=null;
function reorderRuleTo(ruleId,targetId){
  const p=state.selected;if(!p)return;
  const from=p.rules.findIndex(r=>r.id===ruleId),to=p.rules.findIndex(r=>r.id===targetId);
  if(from<0||to<0||from===to)return;
  const [rule]=p.rules.splice(from,1);
  p.rules.splice(to,0,rule);
  dragRuleId=null;renderRules();saveSelected();toast('Rule order saved');
}
function bindRuleDrag(box){
  box.querySelectorAll('.rule-card[draggable="true"]').forEach(card=>{
    card.addEventListener('dragstart',e=>{dragRuleId=card.dataset.ruleId;card.classList.add('dragging');if(e.dataTransfer){e.dataTransfer.effectAllowed='move';try{e.dataTransfer.setData('text/plain',dragRuleId)}catch{}}});
    card.addEventListener('dragend',()=>{dragRuleId=null;card.classList.remove('dragging');box.querySelectorAll('.rule-card').forEach(c=>c.classList.remove('drop-target'))});
    card.addEventListener('dragover',e=>{if(!dragRuleId||dragRuleId===card.dataset.ruleId)return;e.preventDefault();if(e.dataTransfer)e.dataTransfer.dropEffect='move';box.querySelectorAll('.rule-card').forEach(c=>c.classList.toggle('drop-target',c===card))});
    card.addEventListener('dragleave',()=>card.classList.remove('drop-target'));
    card.addEventListener('drop',e=>{e.preventDefault();card.classList.remove('drop-target');if(!dragRuleId||dragRuleId===card.dataset.ruleId)return;reorderRuleTo(dragRuleId,card.dataset.ruleId)});
  });
}

function renderRules(){const p=state.selected;const box=$('#rules-list');$('#add-rule').disabled=!p;if(!p){box.innerHTML='<div class="empty-state">Pick a preset to edit its rules.</div>';$('#editor-title').textContent='Preset rules';$('#editor-sub').textContent='Pick a preset to see its rules';return}refreshRuleActionOptions();$('#editor-title').textContent=p.name;$('#editor-sub').textContent=`${p.rules.length} rules · ${p.description||'Set the gifts that trigger actions'}`;box.innerHTML=p.rules.length?p.rules.map((r,idx)=>`<div class="rule-card ${r.enabled?'':'disabled'}" draggable="true" data-rule-id="${esc(r.id)}" data-index="${idx}"><span class="rule-order" title="Drag to reorder"><span class="rule-grip">⠿</span><span class="rule-pos">${idx+1}</span></span><span class="rule-icon">${r.trigger.type==='gift'?giftArt(r.trigger.gift_name,r.trigger.gift_id,'rule-gift-art'):`<span class="rule-icon-symbol">${triggerSymbols[r.trigger.type]||'·'}</span>`}</span><div><div class="rule-name">${esc(r.name||`${r.trigger.gift_name||r.trigger.type} → ${r.action.type}`)}</div><div class="rule-trigger-label">${esc((r.trigger.type==='gift'?localizedGift(r.trigger.gift_name):r.trigger.keyword||typePL[r.trigger.type]||r.trigger.type))}${r.trigger.like_threshold?` · ${r.trigger.like_threshold}${r.trigger.like_global?' (all viewers)':''}`:''}${r.trigger.min_coins!=null?` · ${Number(r.trigger.min_coins)}+ coins${r.trigger.max_coins!=null?` (up to ${Number(r.trigger.max_coins)})`:''}`:''} ${r.interrupt?'· PRIORITY':''}${r.sound?' · ♫ SOUND':''}</div></div><div class="rule-action-label"><span>→</span>${esc(actionPL[r.action.type]||r.action.type.replaceAll('_',' '))}</div><div class="rule-card-actions"><button class="tiny-action move" data-move="up" data-rule-id="${esc(r.id)}" title="Move up" ${idx===0?'disabled':''}>↑</button><button class="tiny-action move" data-move="down" data-rule-id="${esc(r.id)}" title="Move down" ${idx===p.rules.length-1?'disabled':''}>↓</button><button class="tiny-action" data-toggle="${esc(r.id)}">${r.enabled?'Enabled':'Disabled'}</button><button class="tiny-action" data-edit="${esc(r.id)}">Edytuj</button></div></div>`).join(''):'<div class="empty-state">This preset has no rules yet. Add the first gift.</div>';bindGiftArt(box);$$('[data-move]').forEach(b=>b.onclick=e=>{e.stopPropagation();moveRule(b.dataset.ruleId,b.dataset.move==='up'?-1:1)});bindRuleDrag(box);$$('[data-toggle]').forEach(b=>b.onclick=()=>{const r=p.rules.find(x=>x.id===b.dataset.toggle);r.enabled=!r.enabled;saveSelected()});$$('[data-edit]').forEach(b=>b.onclick=()=>openRule(p.rules.find(x=>x.id===b.dataset.edit)))}
async function loadPresets(){try{state.presets=await api('/api/presets');const active=(await api('/api/status')).preset;state.active=state.presets.find(p=>p.id===active?.id)||state.presets[0]||null;state.selected=state.selected?state.presets.find(p=>p.id===state.selected.id)||state.active:state.active;if(state.active)syncModeToPreset(state.active.id);renderPresets();renderActive()}catch(e){$('#preset-list').innerHTML=`<div class="empty-state">Could not load the presets: ${esc(e.message)}</div>`;$('#rules-list').innerHTML='<div class="empty-state">Check the connection to the app and refresh the view.</div>'}}
async function selectPreset(id){const p=state.presets.find(x=>x.id===id);if(!p)return;state.selected=p;if(state.active?.id!==p.id){try{await post(`/api/presets/${encodeURIComponent(id)}/activate`);state.active=p;syncModeToPreset(p.id);renderActive();toast(`Aktywowano preset: ${p.name}`)}catch(e){toast(e.message)}}renderPresets()}
async function saveSelected(){if(!state.selected)return;$('#save-state').textContent='● Zapisywanie…';try{state.selected=await api(`/api/presets/${encodeURIComponent(state.selected.id)}`,{method:'PUT',body:JSON.stringify(state.selected)});state.presets=state.presets.map(p=>p.id===state.selected.id?state.selected:p);if(state.active?.id===state.selected.id)state.active=state.selected;renderPresets();renderActive();$('#save-state').textContent='● All changes saved'}catch(e){$('#save-state').textContent='● Could not save';toast(e.message)}}
function refreshTestActionOptions(){const prefix=$('#parkour-game-mode').value==='dropper'?'dropper_':'parkour_';const choices=actionCatalog.filter(x=>x.id.startsWith(prefix));const select=$('#parkour-test-action'),old=select.value;select.innerHTML=choices.map(x=>`<option value="${esc(x.id)}">${esc(x.label)}</option>`).join('');if(choices.some(x=>x.id===old))select.value=old}
function refreshRuleActionOptions(){const prefix=state.selected?.id==='minecraft-dropper'?'dropper_':'parkour_';const choices=actionCatalog.filter(x=>x.id.startsWith(prefix)),select=$('#rule-action'),old=select.value;select.innerHTML=choices.map(x=>`<option value="${esc(x.id)}">${esc(x.label)}</option>`).join('');if(choices.some(x=>x.id===old))select.value=old;else if(choices.length)select.value=choices[0].id}
function updateMinecraftModeUI(){const dropper=$('#parkour-game-mode').value==='dropper';$('#minecraft-mode-title').textContent=dropper?'Minecraft · Dropper Arena':'Minecraft · Parkour 100 Levels';$('#minecraft-mode-subtitle').textContent=dropper?'GiftStream generates a local Dropper arena with five shafts and water landings.':'GiftStream downloads the official server and runs the bundled 100 Levels map locally.';$('#parkour-enabled-label').textContent=dropper?'Send Dropper preset actions to the local game':'Send Parkour preset actions to the local game';refreshTestActionOptions()}
function fillActionOptions(){api('/api/actions').then(a=>{actionCatalog=a;refreshRuleActionOptions();refreshTestActionOptions();updateActionHelp()})}
function updateActionHelp(){const descriptions={parkour_push:'Shoots a Punch II arrow straight into the player from one block away, so it always lands — even against a wall; light damage, strong knockback.',parkour_level_forward:'Teleports the player to the map\'s real checkpoint of the next level (from the world data), up to level 100.',parkour_level_back:'Teleports the player to the map\'s real checkpoint of the previous level, never below level 1.',parkour_checkpoint:'Sends the player back to the checkpoint plate of the level they are standing on.',parkour_jail:'Lifts the player into a small floating cage (iron bars, glass floor and roof) two blocks above the ground for 20 seconds, then drops them back where they stood. The cage only fills air, so the course can never be damaged.',parkour_reset:'Starts the 60-second map reset countdown.',parkour_antireset:'Cancels the running reset countdown.',parkour_slow:'Applies Slowness for 7 seconds.',parkour_blind:'Applies Darkness for 4 seconds.',parkour_blackout:'Blackout: Darkness + Blindness for 15 seconds — you can barely see. Daylight stays on.',parkour_lightning:'Strikes lightning at the player.',parkour_disco:'End-rod and note particles around the player.',parkour_heart:'Hearts and a thank-you for a new follower, without speeding the run up.',parkour_jump:'High jump with slow falling for a safe landing.',parkour_shield:'Damage resistance for 6 seconds.',parkour_cleanse:'Removes negative effects without touching positive ones.',dropper_push:'Fires a Punch II arrow at the player inside the shaft.',dropper_level_forward:'Moves to the next of the 100 Dropper levels.',dropper_level_back:'Moves to the previous Dropper level.',dropper_reset:'Teleports back to the start of level 1/100.',dropper_slow:'Applies Slowness for 7 seconds.',dropper_blind:'Applies Darkness for 4 seconds.',dropper_blackout:'Blackout in the shaft: Darkness + Blindness for 15 seconds.',dropper_lightning:'Strikes lightning at the player.',dropper_disco:'End-rod and note particles inside the shaft.',dropper_heart:'Hearts and a thank-you for a new follower.',dropper_jump:'High jump with slow falling.',dropper_shield:'Damage resistance for 6 seconds.',dropper_cleanse:'Removes negative effects.'};$('#action-help').textContent=descriptions[$('#rule-action').value]||'This action runs in local Minecraft mode.'}
function renderRuleSoundChoice(ruleSound=''){const select=$('#rule-sound-choice'),globalUrl=state.liveConfig.sound_url||'';state.ruleSoundChoice=ruleSound||null;const isStudio=!!ruleSound&&ruleSound===globalUrl;select.value=isStudio?'studio':ruleSound?'custom':'';$('#rule-sound-url').value=!isStudio?(ruleSound||''):'';$('#rule-sound-url').classList.toggle('hidden',select.value!=='custom');$('#rule-sound-test').disabled=!(isStudio?globalUrl:select.value==='custom'?ruleSound:'')}
function giftPickerKey(g){return g.id!=null?`id:${g.id}`:`name:${String(g.name||'').toLowerCase()}`}
function renderRuleGiftPicker(query='') {const select=$('#rule-gift'),box=$('#rule-gift-options'),needle=String(query||'').trim().toLocaleLowerCase('en-US');if(!select||!box)return;const options=state.gifts||[];select.innerHTML=options.map(g=>`<option value="${esc(giftPickerKey(g))}">${esc(localizedGift(g.name,g.label_pl))}</option>`).join('');const selected=state.ruleGiftChoice||options[0]||null;if(selected){select.value=giftPickerKey(selected);$('#rule-gift-selected').innerHTML=`${giftArt(selected.name,selected.id,'rule-picker-art')}<span><b>${esc(localizedGift(selected.name,selected.label_pl))}</b><small>${esc(coinText(selected.coins,selected.coins_estimated))}</small></span><i>SELECTED</i>`}else{$('#rule-gift-selected').innerHTML='<span>◇</span><small>No gifts in the catalog — refresh the library</small>'}const matches=options.filter(g=>!needle||`${g.name||''} ${g.label_pl||''} ${g.id||''}`.toLocaleLowerCase('en-US').includes(needle));const shown=matches.slice(0,needle?30:12);box.innerHTML=shown.map(g=>`<button class="rule-gift-option ${selected&&giftPickerKey(selected)===giftPickerKey(g)?'selected':''}" type="button" role="option" aria-selected="${!!selected&&giftPickerKey(selected)===giftPickerKey(g)}" data-rule-gift="${esc(giftPickerKey(g))}">${giftArt(g.name,g.id,'rule-option-art')}<span><b>${esc(localizedGift(g.name,g.label_pl))}</b><small>${esc(g.name)} · ${esc(coinText(g.coins,g.coins_estimated))}</small></span></button>`).join('')||'<div class="rule-gift-empty">No gifts found. Try the English gift name or refresh the catalog.</div>';if(matches.length>shown.length)box.insertAdjacentHTML('beforeend',`<div class="rule-gift-empty">Showing ${shown.length} of ${matches.length} results — refine your search.</div>`);box.querySelectorAll('[data-rule-gift]').forEach(button=>button.onclick=()=>{state.ruleGiftChoice=options.find(g=>giftPickerKey(g)===button.dataset.ruleGift)||null;select.value=state.ruleGiftChoice?giftPickerKey(state.ruleGiftChoice):'';renderRuleGiftPicker('');$('#rule-gift-search').value='';$('#rule-gift-search').focus()});bindGiftArt(box);bindGiftArt($('#rule-gift-selected'))}
function fillGifts(){return api('/api/gifts?sort=popular').then(a=>{state.gifts=a;state.displayGifts=a;renderRuleGiftPicker($('#rule-gift-search')?.value||'');renderRules();if($('#view-gifts').classList.contains('active'))renderGiftLibrary();return a})}
