function openRule(rule=null){if(!state.selected)return;const form=$('#rule-form');form.reset();$('#rule-id').value=rule?.id||'';$('#rule-modal-title').textContent=rule?'Edit rule':'Add rule';$('#rule-name').value=rule?.name||'';$('#rule-trigger').value=rule?.trigger?.type||'gift';const catalogGift=(rule?.trigger?.gift_id!=null?state.gifts.find(g=>String(g.id)===String(rule.trigger.gift_id)):null)||state.gifts.find(g=>String(g.name).toLowerCase()===String(rule?.trigger?.gift_name||'Rose').toLowerCase());state.ruleGiftChoice=catalogGift||(rule?.trigger?.gift_name?{id:rule.trigger.gift_id,name:rule.trigger.gift_name,label_pl:localizedGift(rule.trigger.gift_name),coins:0,coins_estimated:true}:state.gifts[0]||null);$('#rule-gift-search').value='';renderRuleGiftPicker('');$('#rule-min-coins').value=rule?.trigger?.min_coins??'';$('#rule-max-coins').value=rule?.trigger?.max_coins??'';$('#rule-keyword').value=rule?.trigger?.keyword||'';$('#rule-threshold').value=rule?.trigger?.like_threshold||100;$('#rule-like-global').checked=!!rule?.trigger?.like_global;$('#rule-action').value=rule?.action?.type||'parkour_push';$('#rule-cooldown').value=rule?.cooldown_sec||0;$('#rule-user-cooldown').value=rule?.user_cooldown_sec||0;$('#rule-params').value=JSON.stringify(rule?.action?.params||{count:1});$('#rule-alert').value=cleanEmoji(rule?.alert_text||'');renderRuleSoundChoice(rule?.sound||'');$('#rule-interrupt').checked=!!rule?.interrupt;toggleRuleFields();$('#rule-dialog').showModal()}
