async function loadLiveTools(){try{const c=await api('/api/config');state.liveConfig={...state.liveConfig,...c,tts_enabled:!!c.tts_enabled,tts_voice:c.tts_voice||'en-US',sound_alerts:!!c.sound_alerts,sound_volume:Number(c.sound_volume??.55),sound_url:c.sound_url||'',sound_label:c.sound_label||'',overlay_template:['grid','list','minimal','streamer','ticker','spotlight','arena'].includes(c.overlay_template)?c.overlay_template:'grid'};const overlayChoice=$(`input[name="template"][value="${state.liveConfig.overlay_template}"]`);if(overlayChoice){overlayChoice.checked=true;$$('.template-option').forEach(x=>x.classList.toggle('selected',x.contains(overlayChoice)))}$('#overlay-theme').value=['mint','violet','amber','ocean'].includes(c.overlay_theme)?c.overlay_theme:'mint';$('#overlay-accent').value=/^#[0-9a-f]{6}$/i.test(c.overlay_accent||'')?c.overlay_accent:'#8cf0bc';$('#overlay-scale').value=Math.round((Number(c.overlay_scale)||1)*100);$('#overlay-title').value=c.overlay_title||'';const overlayFields=new Set(String(c.overlay_fields||'earnings,gifts,actions,viewers,likes,leaderboard').split(','));$$('[data-overlay-field]').forEach(x=>x.checked=overlayFields.has(x.dataset.overlayField));$('#overlay-opacity').value=Math.round((Number(c.overlay_opacity)||.72)*100);$('#overlay-density').value=['compact','balanced','bold'].includes(c.overlay_density)?c.overlay_density:'balanced';$('#overlay-canvas').value=['landscape','portrait'].includes(c.overlay_canvas)?c.overlay_canvas:'landscape';state.liveConfig.overlay_positions_landscape=c.overlay_positions_landscape||state.liveConfig.overlay_positions_landscape;state.liveConfig.overlay_positions_portrait=c.overlay_positions_portrait||state.liveConfig.overlay_positions_portrait;updateOverlayPreview();$('#tts-enabled').checked=state.liveConfig.tts_enabled;$('#tts-voice').value=state.liveConfig.tts_voice;$('#sound-alerts').checked=state.liveConfig.sound_alerts;$('#sound-volume').value=Math.round(state.liveConfig.sound_volume*100);$('#sound-volume-label').textContent=`${Math.round(state.liveConfig.sound_volume*100)}%`;$('#sound-url').value=state.liveConfig.sound_url;renderSelectedSound()}catch{}}
