async function saveSoundUrl(){const value=$('#sound-url').value.trim(),old=state.liveConfig.sound_url;try{const saved=await api('/api/config',{method:'PUT',body:JSON.stringify({sound_url:value,sound_label:value?'Custom audio link':''})});state.liveConfig.sound_url=saved.sound_url||'';state.liveConfig.sound_label=saved.sound_label||'';$('#sound-url').value=state.liveConfig.sound_url;renderSelectedSound();toast(state.liveConfig.sound_url?'Custom sound saved':'Built-in sound restored')}catch(e){toast(e.message)}}
async function uploadSound(){const input=$('#sound-file'),file=input.files?.[0],button=$('#upload-sound'),status=$('#sound-upload-status');if(!file){status.textContent='Select an audio file first.';return}if(file.size>10*1024*1024){status.textContent='Plik przekracza limit 10 MB.';return}button.disabled=true;status.textContent='Uploading and saving the file…';const old=state.liveConfig.sound_url;try{const response=await fetch(`/api/sounds/upload?filename=${encodeURIComponent(file.name)}`,{method:'POST',headers:{'Content-Type':file.type||'application/octet-stream'},body:file,cache:'no-store'});const asset=await response.json();if(!response.ok)throw new Error(asset.detail||'Could not save the file');const saved=await api('/api/config',{method:'PUT',body:JSON.stringify({sound_url:asset.url,sound_label:file.name.slice(0,100),sound_alerts:true})});state.liveConfig={...state.liveConfig,...saved};$('#sound-url').value=state.liveConfig.sound_url;$('#sound-alerts').checked=true;renderSelectedSound();status.textContent=`Gotowe: ${file.name} · ${(file.size/1024).toFixed(0)} KB`;toast('Custom sound uploaded and selected')}catch(e){status.textContent=e.message;toast(e.message)}finally{button.disabled=false;input.value=''}}
