function renderSelectedSound(){const label=state.liveConfig.sound_label||'';let host='';try{host=new URL(state.liveConfig.sound_url).hostname.toLowerCase()}catch{}const url=state.liveConfig.sound_url||'';$('#sound-selected-title').textContent=label||'GiftStream sound';$('#sound-selected-subtitle').textContent=url?url.startsWith('/api/sounds/uploads/')?'Plik zapisany lokalnie':(['www.myinstants.com','myinstants.com'].includes(host)?'MyInstants · ready to test':'Saved audio link'):'GiftStream built-in sound';$('#sound-ready-pill').textContent=url?'SELECTED':'GOTOWY';$('#clear-sound').disabled=!url}
async function selectMyInstant(sound){const old=state.liveConfig.sound_url;try{const saved=await api('/api/config',{method:'PUT',body:JSON.stringify({sound_url:sound.url,sound_label:sound.name,sound_alerts:true})});state.liveConfig={...state.liveConfig,...saved};$('#sound-url').value=state.liveConfig.sound_url;$('#sound-alerts').checked=true;renderSelectedSound();toast(`Ustawiono alert: ${sound.name}`)}catch(e){toast(e.message)}}
function playAudioClip(url,reportError=false){try{const audio=new Audio(url),volume=Number(state.liveConfig.sound_volume);audio.volume=Math.max(0,Math.min(1,Number.isFinite(volume)?volume:.55));audio.preload='auto';let stopTimer;audio.addEventListener('playing',()=>{stopTimer=setTimeout(()=>audio.pause(),MAX_SOUND_CLIP_SECONDS*1000)},{once:true});audio.addEventListener('ended',()=>clearTimeout(stopTimer),{once:true});audio.play().catch(()=>{if(reportError)toast('Could not play the sound. Check the link and your browser autoplay settings.')});return audio}catch{if(reportError)toast('Could not play the sound. Check the link and your browser autoplay settings.');return null}}function previewSound(url){return playAudioClip(url,true)}
async function clearActivity(){try{const result=await post('/api/stats/clear-activity');await refreshSnapshot();toast(result.message)}catch(e){toast(e.message)}}
async function resetStats(){if(!window.confirm('Reset counters, viewer ranking, activity and action stats for the current session?'))return;const button=$('#reset-stats');button.disabled=true;try{const result=await post('/api/stats/reset');await refreshSnapshot();toast(result.message)}catch(e){toast(e.message)}finally{button.disabled=false}}
async function searchMyInstants(){const query=$('#myinstants-query').value.trim(),box=$('#myinstants-results'),button=$('#myinstants-search-button');if(!query){box.innerHTML='<div class="sound-empty"><strong>Type a sound name to start searching.</strong></div>';$('#myinstants-query').focus();return}button.disabled=true;button.textContent='Szukam…';box.innerHTML='<div class="sound-empty"><span class="sound-loading"></span><strong>Connecting to MyInstants…</strong><small>Results will appear here.</small></div>';try{const result=await api(`/api/sounds/myinstants?q=${encodeURIComponent(query)}`);box.replaceChildren();if(!result.results?.length){box.innerHTML='<div class="sound-empty"><span>⌕</span><strong>No matching audio files found</strong><small>Try a shorter term, e.g. “bruh”, “victory” or “applause”.</small></div>';return}for(const sound of result.results){const row=document.createElement('article');row.className='myinstants-result';const number=document.createElement('span');number.className='sound-result-mark';number.textContent='♫';const text=document.createElement('div');text.className='sound-result-copy';const name=document.createElement('strong');name.textContent=sound.name;const host=document.createElement('small');host.textContent='MYINSTANTS · MP3';text.append(name,host);const preview=document.createElement('button');preview.type='button';preview.className='button button-secondary small';preview.textContent='▶ Preview';preview.setAttribute('aria-label',`Preview ${sound.name}`);preview.onclick=()=>previewSound(sound.url);const add=document.createElement('button');add.type='button';add.className='button button-primary small';add.textContent=state.liveConfig.sound_url===sound.url?'Selected ✓':'Set alert';add.disabled=state.liveConfig.sound_url===sound.url;add.onclick=()=>selectMyInstant(sound);row.append(number,text,preview,add);box.append(row)}}catch(e){box.innerHTML=`<div class="sound-error"><strong>The MyInstants search is not responding right now</strong><small>${esc(e.message)}. You can also paste a public HTTPS link on the right.</small></div>`}finally{button.disabled=false;button.innerHTML='Search sounds <span>⌕</span>'}}
function speakText(text,voice=state.liveConfig.tts_voice){if(!('speechSynthesis'in window)||!text)return;try{speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang=voice;utterance.rate=1;utterance.pitch=1;const match=speechSynthesis.getVoices().find(v=>v.lang.toLowerCase().startsWith(voice.toLowerCase()));if(match)utterance.voice=match;speechSynthesis.speak(utterance)}catch{}}
function speakLiveEvent(ev){if(!state.liveConfig.tts_enabled||!ev||Date.now()-state.lastSpeechAt<2200)return;if(!['gift','follow','subscribe'].includes(ev.type))return;state.lastSpeechAt=Date.now();const who=ev.nickname||ev.user||'Viewer';const gift=localizedGift(ev.gift_name);speakText(ev.type==='gift'?`${who} sent the gift ${gift}${ev.repeat_count>1?` ×${ev.repeat_count}`:''}`:ev.type==='follow'?`${who} started following the channel`:`${who} subscribed to the channel`)}
function playSoundUrl(url,reportError=false){playAudioClip(url,reportError)}
function playSoundAlert(force=false){if(!force&&!state.liveConfig.sound_alerts)return;try{if(state.liveConfig.sound_url){playSoundUrl(state.liveConfig.sound_url);return}const AudioContextClass=window.AudioContext||window.webkitAudioContext;if(!AudioContextClass)return;const context=state.audioContext||(state.audioContext=new AudioContextClass());if(context.state==='suspended')context.resume();const osc=context.createOscillator(),gain=context.createGain(),now=context.currentTime;osc.type='sine';osc.frequency.setValueAtTime(880,now);osc.frequency.exponentialRampToValueAtTime(1174,now+.12);gain.gain.setValueAtTime(Math.max(.001,state.liveConfig.sound_volume*.12),now);gain.gain.exponentialRampToValueAtTime(.001,now+.28);osc.connect(gain);gain.connect(context.destination);osc.start(now);osc.stop(now+.3)}catch{}}
function announceEvent(ev){if(['gift','follow','subscribe'].includes(ev?.type)&&Date.now()-state.lastSoundAt>700){state.lastSoundAt=Date.now();playSoundAlert()}speakLiveEvent(ev)}
