/* Public API for web/sounds.js (Studio: trimming and the file library). */
async function selectSoundUrl(url,label=''){
  const saved=await api('/api/config',{method:'PUT',body:JSON.stringify({sound_url:url||'',sound_label:label||'',sound_alerts:true})});
  state.liveConfig={...state.liveConfig,...saved};
  if($('#sound-url'))$('#sound-url').value=state.liveConfig.sound_url;
  if($('#sound-alerts'))$('#sound-alerts').checked=!!state.liveConfig.sound_alerts;
  renderSelectedSound();
  toast(label?`Ustawiono alert: ${label}`:'Trimmed sound selected');
  return state.liveConfig;
}
window.GiftStream={get state(){return state},api,esc,previewSound,selectSoundUrl,
  MAX_SOUND_CLIP_SECONDS,renderSelectedSound};
setup();
